#!/usr/bin/env bash
# gen-stand-runner-manifest.sh — regenerate the host-runner hash-pin manifest.
#
# stand-runner.sh (sha256 pin over the immutable CODE_ROOT) refuses to run when
# a file is missing or changed. That pin used to be regenerated by hand after
# every Deploy Dev; a forgotten step rejected every preview deploy with
# "manifest-mismatch". This script is the single generator, invoked by the
# Deploy Dev workflow right after the checkout is pinned.
#
# Usage: gen-stand-runner-manifest.sh <root> <out>
#   <root>  immutable runner code root (contains tools/ and deploy/)
#   <out>   manifest path (default /srv/archkit/dev/stand-runner/manifest.sha256)
#
# Format: "<sha256>  <relpath>" sorted by path. Runtime/temp files are excluded:
# the manifest covers source, not stand runtime state or bytecode caches.
set -euo pipefail

root="${1:-}"
out="${2:-/srv/archkit/dev/stand-runner/manifest.sha256}"
[ -n "$root" ] || { echo "usage: $0 <root> [manifest-out]" >&2; exit 2; }
[ -d "$root" ] || { echo "gen-stand-runner-manifest: root not found: $root" >&2; exit 2; }
root="$(cd "$root" && pwd -P)"
[ -d "$root/tools" ] || { echo "gen-stand-runner-manifest: $root/tools is missing" >&2; exit 2; }
[ -d "$root/deploy" ] || { echo "gen-stand-runner-manifest: $root/deploy is missing" >&2; exit 2; }

mkdir -p -- "$(dirname "$out")"
# Same directory as the destination: mv is a rename, not a truncating copy.
tmp="$(mktemp "$(dirname "$out")/.manifest.XXXXXX")"
cleanup() { rm -f -- "$tmp"; }
trap cleanup EXIT

(
  cd "$root"
  find tools deploy -type f \
    ! -path '*/__pycache__/*' \
    ! -name '*.pyc' \
    ! -name '*.pyo' \
    ! -name '*.swp' \
    ! -name '*~' \
    ! -path 'deploy/stands/.runtime/*' \
    -print0 \
    | LC_ALL=C sort -z \
    | xargs -0 --no-run-if-empty sha256sum
) > "$tmp"

count="$(wc -l < "$tmp" | tr -d '[:space:]')"
[ -n "$count" ] && [ "$count" -gt 0 ] || {
  echo "gen-stand-runner-manifest: refusing to write an empty manifest" >&2
  exit 1
}

# Atomic replace so a concurrent runner never reads a half-written pin.
chmod 0644 -- "$tmp"
mv -f -- "$tmp" "$out"
echo "gen-stand-runner-manifest: $count files -> $out"
